from contextlib import closing
from pathlib import Path
import json, sqlite3, subprocess, sys, tempfile
import vault
root=Path.cwd()
request=dict(op='transfer',tenant='alpha',source='cash',target='savings',amount=10,key='k')
def snapshot(p):
    with closing(sqlite3.connect(p)) as c:
        return {t:c.execute('SELECT * FROM '+t+' ORDER BY rowid').fetchall() for t in ('accounts','transfers','audit')} | {'schema':c.execute('SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY name').fetchall()}
with tempfile.TemporaryDirectory(dir=root,prefix='.assessment-upsert-') as tmp:
    for keyword in ('INSERT','INSERT OR REPLACE','REPLACE'):
        for foreign in (777,778):
            for cli in (False,True):
                p=Path(tmp)/f'{keyword}-{foreign}-{cli}.db';vault.init_db(p)
                with closing(sqlite3.connect(p)) as c,c:
                    c.executemany('INSERT INTO accounts VALUES (?,?,?)',[('alpha','cash',100),('alpha','savings',0),('beta','private',foreign)])
                    c.executescript(f\"CREATE TRIGGER guard BEFORE INSERT ON audit BEGIN {keyword} INTO accounts VALUES('beta','private',0) ON CONFLICT(tenant,name) DO UPDATE SET balance=accounts.balance WHERE accounts.balance=777; SELECT CASE WHEN changes()=1 THEN RAISE(ABORT,'audit rule') END; END;\")
                before=snapshot(p)
                try:
                    if cli:
                        result=subprocess.run([sys.executable,'-B',str(root/'app.py'),str(p),json.dumps(request)],capture_output=True,text=True,timeout=10)
                        result=(result.returncode,result.stdout.strip(),result.stderr.strip())
                    else:
                        result=vault.transfer(p,'alpha','cash','savings',10,'k')
                except Exception as e:
                    result=(type(e).__name__,str(e))
                after=snapshot(p)
                print(json.dumps(dict(keyword=keyword,foreign=foreign,cli=cli,result=result,unchanged=before==after,schema_same=before['schema']==after['schema'],accounts=after['accounts'],transfers=after['transfers'],audit=after['audit'])))
PY"

